class OrderRow extends StatelessWidget {
  const OrderRow({super.key, required this.title});
  final String title;

  @override
  Widget build(BuildContext context) => Padding(
        // Physical sides: they stay put when the layout flips
        padding: const EdgeInsets.only(left: 16, right: 8),
        child: Row(children: [
          Expanded(child: Text(title, textAlign: TextAlign.left)),
          const Icon(Icons.keyboard_arrow_right), // never mirrored
        ]),
      );
}

class OrderRow extends StatelessWidget {
  const OrderRow({super.key, required this.title});
  final String title;

  @override
  Widget build(BuildContext context) => Padding(
        // start and end resolve against the ambient Directionality
        padding: const EdgeInsetsDirectional.only(start: 16, end: 8),
        child: Row(children: [
          Expanded(child: Text(title, textAlign: TextAlign.start)),
          const Icon(Icons.chevron_right), // matchTextDirection: true
        ]),
      );
}
